using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using SporeGobbo.Geometry;
using SporeGobbo.Geometry.Preview;
namespace SporeGobbo.CampCandidate.Preview
{
 [DefaultExecutionOrder(-2500)]public sealed class Stage58CaveBenchmark:MonoBehaviour
 {
  [Serializable]public class Frame{public int frame,known,pending,resident,built,evicted;public string phase;public double interval,discovery,publication,structure,main,render,gpu,encounter;public long allocation;public bool ready;}
  [Serializable]public class Metric{public string name;public int frame,count;public double ms;}
  [Serializable]public class Result{public string error="";public List<Frame> frames=new List<Frame>(10000);public List<Metric> events=new List<Metric>();public List<string> checks=new List<string>();}
  Stage55Preview env;Stage47Preview live;Stage58Telemetry telemetry;string output;Result data=new Result();readonly WaitForEndOfFrame end=new WaitForEndOfFrame();
  IEnumerator Start(){var args=Environment.GetCommandLineArgs();int n=Array.IndexOf(args,"-stage58CaveOutput");if(n<0)yield break;output=args[n+1];Directory.CreateDirectory(output);telemetry=new Stage58Telemetry(output);telemetry.StartCapture("cave-cold");long t=System.Diagnostics.Stopwatch.GetTimestamp();env=GetComponent<Stage55Preview>();env.Initialize();MetricScope("cold-initialization",t);env.automation=true;env.showPanel=false;env.Lab.paused=true;live=env.Live;live.automation=true;Application.runInBackground=true;QualitySettings.vSyncCount=0;Application.targetFrameRate=60;yield return Settle();telemetry.StopCapture();yield return Capture("01-cave-start");
   // Real-time circuit, with the existing logical clearance and swept movement.
   telemetry.StartCapture("cave-exploration");double start=Time.realtimeSinceStartupAsDouble;int waypoint=1,cursor=0;List<Point2> path=null;while(Time.realtimeSinceStartupAsDouble-start<60){double tick=Time.realtimeSinceStartupAsDouble,dt=Math.Min(.05,Time.unscaledDeltaTime);if(path==null){UnityEngine.Profiling.Profiler.BeginSample("SG58.CaveNavigation");var nav=new LabNavigation(live.World,new Point2(live.Position.x,live.Position.y));path=new List<Point2>();bool ok=nav.TraceToRoot(env.State.Fixture.Tour[waypoint],1,path);UnityEngine.Profiling.Profiler.EndSample();Check(ok,"Cave circuit path "+waypoint);if(!ok)break;path.Reverse();cursor=0;}if(live.Ready){if(cursor<path.Count){var move=Stage55Preview.V(path[cursor])-live.Position;if(move.magnitude<.01)cursor++;else live.Step(Vector2.ClampMagnitude(move/(float)(10*Math.Max(.001,dt)),1),move,false,(float)dt);}else{waypoint=(waypoint+1)%env.State.Fixture.Tour.Count;path=null;}}env.Process(dt);yield return end;Record("real-time-exploration",tick);}telemetry.StopCapture();yield return Capture("02-cave-explored");
   env.ResetDemo();live.Teleport(Stage55Preview.V(env.State.Fixture.P(-15,10)));yield return Settle();telemetry.StartCapture("small-pocket");yield return ExcavateTo(env.State.Fixture.P(-31,4),"small-pocket");yield return Frames("small-reveal",2);telemetry.StopCapture();
   env.ResetDemo();live.Teleport(Stage55Preview.V(env.State.Fixture.P(-60,-4)));yield return Settle();telemetry.StartCapture("large-chamber");yield return ExcavateTo(env.State.Fixture.P(-77,12),"large-chamber");yield return Frames("large-reveal",3);telemetry.StopCapture();
   env.ResetDemo();live.Teleport(Stage55Preview.V(env.State.Fixture.P(76,-1)));yield return Settle();telemetry.StartCapture("network");yield return ExcavateTo(env.State.Fixture.P(94,-25),"network");yield return Frames("bounded-network",3);telemetry.StopCapture();
   env.ResetDemo();live.Teleport(Stage55Preview.V(env.State.Fixture.P(-28,-28)));env.Lab.paused=false;yield return Settle();telemetry.StartCapture("occupied-discovery");yield return ExcavateTo(env.State.Fixture.P(-45,-26),"occupied");yield return Frames("active-encounter-discovery",5);telemetry.StopCapture();env.Lab.paused=true;Check(env.EncounterViolations==0,"No concealed actionable attacks");env.Go(2);yield return Settle();telemetry.StartCapture("landmark-publication");foreach(var offset in new[]{new DualTile(20,-16),new DualTile(21,-16),new DualTile(22,-16),new DualTile(74,-29),new DualTile(75,-29),new DualTile(76,-29)}){long edit=System.Diagnostics.Stopwatch.GetTimestamp();int changed=live.Stream.Dig(new[]{new DualTile(env.State.Fixture.X+offset.X,env.State.Fixture.Y+offset.Y)});env.Process(0);MetricScope("controlled-landmark-edit",edit,changed);yield return null;}yield return Frames("landmark-emergence",3);telemetry.StopCapture();yield return Capture("03-roots");for(int i=0;i<3;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();env.ResetDemo();MetricScope("reset-"+i,t);yield return Settle();}Check(env.State.World.Width==1024,"Existing large fixture unchanged");File.WriteAllText(Path.Combine(output,"result.json"),JsonUtility.ToJson(data,true));telemetry.Dispose();Application.Quit(data.error==""?0:1);}
  IEnumerator ExcavateTo(Point2 target,string label){var source=new Point2(live.Position.x,live.Position.y);var delta=target-source;int steps=(int)Math.Ceiling(LabNavigation.Distance(source,target));var cells=new List<DualTile>();for(int i=1;i<=steps;i++){var p=source+delta*(i/(double)steps);long t=System.Diagnostics.Stopwatch.GetTimestamp();PreviewDigBrush.Cells(Stage55Preview.V(p),DigBrush.ThreeWide,2.2f,live.World,cells);int changed=live.Stream.Dig(cells);env.Process(Math.Min(.05,Time.unscaledDeltaTime));MetricScope(label+"-edit",t,changed);int guard=0;while(Vector2.Distance(live.Position,Stage55Preview.V(p))>.005f&&guard++<1800){double tick=Time.realtimeSinceStartupAsDouble,dt=Math.Min(.05,Time.unscaledDeltaTime);var movement=Stage55Preview.V(p)-live.Position;if(live.Ready)live.Step(Vector2.ClampMagnitude(movement/(float)(10*Math.Max(.001,dt)),1),movement,false,(float)dt);env.Process(dt);if(!env.Lab.paused)env.AdvanceEncounters(dt);yield return end;Record(label+"-excavation",tick);}Check(guard<1800,"Swept route "+label+" "+i);}Check(Vector2.Distance(live.Position,Stage55Preview.V(target))<.02,"Connected excavation "+label);}
  IEnumerator Frames(string phase,double seconds){double start=Time.realtimeSinceStartupAsDouble;while(Time.realtimeSinceStartupAsDouble-start<seconds){double tick=Time.realtimeSinceStartupAsDouble,dt=Math.Min(.05,Time.unscaledDeltaTime);env.Process(dt);if(!env.Lab.paused)env.AdvanceEncounters(dt);yield return end;Record(phase,tick);}}
  void Record(string phase,double start){data.frames.Add(new Frame{frame=Time.frameCount,phase=phase,interval=(Time.realtimeSinceStartupAsDouble-start)*1000,discovery=env.DiscoveryMs,publication=live.Stream.PresentationMs,structure=env.StructureMs,encounter=env.EncounterMs,main=telemetry.Main.Valid?telemetry.Main.LastValue*1e-6:-1,render=telemetry.Render.Valid?telemetry.Render.LastValue*1e-6:-1,gpu=telemetry.GpuMs(),allocation=telemetry.Allocation.Valid?telemetry.Allocation.LastValue:-1,known=env.State.Discovery.Remembered.Count,pending=env.State.Discovery.PendingReleases+live.Stream.PendingPresentation,resident=live.Stream.Resident.Count,built=live.Stream.TotalBuilt,evicted=live.Stream.TotalEvicted,ready=live.Ready});}
  IEnumerator Settle(){int i=0;do{env.Process(Math.Min(.05,Time.unscaledDeltaTime),false);yield return null;if(++i>6000){Check(false,"Cave readiness timeout");yield break;}}while(!live.Ready||live.Stream.PendingPresentation>0||env.State.Discovery.PendingReleases>0);for(i=0;i<5;i++)yield return null;}
  IEnumerator Capture(string name){yield return Settle();env.CameraStudy.Capture(output,name);while(env.CameraStudy.CapturePending)yield return null;env.CameraStudy.captureLabel=false;}
  void MetricScope(string name,long start,int count=0)=>data.events.Add(new Metric{name=name,frame=Time.frameCount,ms=StreamingGeometry.Elapsed(start),count=count});
  void Check(bool okay,string label){data.checks.Add((okay?"PASS ":"FAIL ")+label);if(!okay)data.error+=label+";";}
 }
}
